/* the bar always fits: if the sections do not fit beside the title and the tools, the title's words go first, then the
   longer section names shorten, then the tour button keeps only its picture, and only then do the sections move into Menu.
   Measured on the reader's own screen and fonts, so nothing ever overlaps */
const FIT=['rdf1','rdf2','rdf3','rdfi','rdfia','rdf4'];
function overNow(){if(R.classList.contains('rdf4'))return false;const ul=$('.rdl1',rn);if(!ul)return false;
 const a=ul.getBoundingClientRect(),b=rn.getBoundingClientRect();if(a.width>b.width+1)return true;
 const bb=brand?brand.getBoundingClientRect():null,nx=[sb,nb,ct].map(x=>x&&x.getBoundingClientRect()).filter(x=>x&&x.width);
 if(bb&&a.left<bb.right-1)return true;if(nx.some(x=>a.right>x.left+1&&x.left>a.left))return true;
 /* round 6: the buttons on the right overlapping one another, or Take a tour too narrow for its words */
 const sx=nx.slice().sort((p,q)=>p.left-q.left);for(let i=1;i<sx.length;i++)if(sx[i-1].right>sx[i].left+1)return true;
 if(nb&&nb.offsetParent&&!R.classList.contains('rdf3')&&nb.scrollWidth>nb.clientWidth+1)return true;if(sb&&nb&&sb.offsetParent&&nb.offsetParent&&!R.classList.contains('rdf3')){const p=sb.getBoundingClientRect(),q=nb.getBoundingClientRect();if(p.right>q.left-4)return true}
 return wrap.scrollWidth>wrap.clientWidth+1}
let fitting=false;
function fitBar(){if(fitting)return;fitting=true;try{FIT.concat(['rdf5','rdf6']).forEach(c=>R.classList.remove(c));
 if(window.CC_PHONE||innerWidth<=760){R.classList.add('rdf4')}else{let i=0;while(i<FIT.length&&overNow()){R.classList.add(FIT[i]);i++}
  /* round 9: once the sections are pictures there is often room again for the title's words and Take a tour's words */
  if(R.classList.contains('rdfi')&&!R.classList.contains('rdf4'))['rdf1','rdf3'].forEach(c=>{R.classList.remove(c);if(overNow())R.classList.add(c)})}
 /* round 9: in Menu, the bar keeps the Menu button and every tool in view: smaller buttons first, then the section's name alone */
 if(R.classList.contains('rdf4'))['rdf5','rdf6'].forEach(c=>{if(wrap.scrollWidth>wrap.clientWidth+1)R.classList.add(c)})
 if(!small())closeMenu(false);navH()}finally{fitting=false}}
